window.FILM_WORK_PROMPTS={"work_id":"src-1fe33f4c8b5fd364","records":[{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-4f83f6ffdd75fb22","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (374).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"人物上半身占据画面左侧，身穿米白色厚重连帽防护服，面部仅露双眼。背景为模糊的灰褐色墙面，右侧留白，整体色调偏暖。","analysis":"构图采用偏左布局，人物头部与肩部占据画面约60%面积。视角平视，焦点锁定在人物眼部，背景虚化明显。光线柔和，从左侧照射，在面部形成自然阴影，米白色织物纹理清晰，与暗色背景形成对比。","prompt":"人物上半身特写，身穿米白色厚实连帽防护服，材质呈现粗糙织物纹理。头部被完全包裹，面部仅通过一个矩形透明视窗露出双眼，视窗边框为浅色硬质材料。人物眼神直视前方，表情平静。背景为虚化的灰褐色建筑墙面，右侧大面积留白。光线柔和自然，色调偏暖，焦点集中在人物眼部，景深极浅，背景完全模糊。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:38:52-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (374).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.519,"observed_resolution":"normal","observation_limits":[],"id":"VP-34a74a418aa533c8","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-ad688564bb98417b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (381).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"金发女性面部特写，神情凝重直视前方，背景为模糊的室内环境，可见左侧家具轮廓与右侧暖色墙面。","analysis":"画面采用中心构图，人物面部占据视觉核心，仅可见头部及肩部上沿。镜头平视，焦点锐利地落在双眼与五官上，背景深度虚化。光线柔和，发丝边缘有高光勾勒，面部受光均匀，背景呈现暖褐色调，与人物冷色调的发丝形成对比。","prompt":"一位金发女性的面部特写，留着齐刘海长直发，发丝在光线下呈现明亮的金色光泽。她双眼圆睁，眼神专注且略带惊愕，嘴唇微张，面部皮肤质感细腻。人物仅露出头部和肩部，身穿浅色衣物。背景处于焦外虚化状态，左侧隐约可见深色家具的轮廓，右侧是模糊的暖褐色墙面或家具，整体色调温暖，光影柔和，营造出一种静谧而紧张的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:38:59-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (381).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.526,"observed_resolution":"normal","observation_limits":[],"id":"VP-159479448d8023f0","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-1b70a056c2476c87","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (379).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"巨大的金属结构从画面顶部垂直向下延伸，由白色A型支架支撑，矗立在开阔的乡村田野中，背景是蓝天与远处的低矮建筑。","analysis":"画面采用极端的仰视视角，巨大的深色金属梁占据画面中心，形成强烈的纵向视觉引导。白色支架呈对称分布，支撑着上方的结构。背景是广阔的蓝天和稀疏的白云，地面是枯黄的草地和泥土路，远处有零星的树木和房屋。光线明亮，色彩对比鲜明，金属的冷硬与自然的柔和形成反差。","prompt":"这是一张仰视视角的户外摄影作品，画面中心是一个巨大的深色金属结构，从顶部垂直向下延伸，仿佛悬挂在空中。该结构由几组白色的A型支架支撑，支架呈对称排列，稳固地立在地面上。背景是晴朗的蓝天，飘浮着几缕淡淡的白云。地面是枯黄的草地和一条泥土路，远处可以看到稀疏的树木、电线杆和低矮的房屋建筑。阳光充足，光影清晰，金属结构的质感与周围自然环境的色调形成鲜明对比，营造出一种超现实的工业与自然融合的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:39:07-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (379).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.511,"observed_resolution":"normal","observation_limits":[],"id":"VP-084ff1ce7303d5d0","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-805a69695b81ea39","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (368).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"一张苍白女性面孔嵌在深色、破碎且带有光泽的块状物质中，周围环绕着不规则的灰黑色碎片，背景中散布着几处模糊的橙黄色亮区。","analysis":"画面主体为一张清晰的女性面部，位于画面左侧偏中位置，仅头部可见。面部周围被大量深色、具有金属或玻璃质感的破碎物质紧密包围，这些物质占据了画面的绝大部分空间。背景深处有几处模糊的橙黄色光斑，与前景的冷灰色调形成对比。光线似乎从上方或前方投射，照亮了面部，使其在黑暗环境中显得格外突出。","prompt":"一张高对比度的特写画面，主体是一张苍白的女性面孔，神情平静，五官清晰，位于画面左侧。面部被包裹在大量深色、破碎且带有光泽的块状物质中，这些物质呈现出类似烧焦的塑料或金属碎片的质感，层层叠叠地堆积在面部周围，占据了画面的大部分空间。背景深处隐约可见几处模糊的橙黄色亮区，与前景的冷灰色调形成鲜明对比。光线从上方投射，照亮了面部，使其在黑暗环境中显得格外突出，整体氛围神秘而压抑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:39:15-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (368).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.536,"observed_resolution":"normal","observation_limits":[],"id":"VP-3c594108b775f47b","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-b7f22f19b4a29d6f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (334).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"画面主体为前景横置的铁路道口栏杆，背景是延伸向树林深处的土路。左侧站立一人，右侧远处有模糊人影，四周被密集的白桦林环绕，地面覆盖枯草。","analysis":"构图以前景栏杆为视觉中心，土路形成纵深引导线。左侧人物全身可见，呈站立姿态，身形在画面中占比极小。右侧远处仅见模糊轮廓。镜头视角平视，光线为阴天漫射光，整体色调偏冷灰，树林深处有微弱亮光，明暗对比平缓，无强烈阴影。","prompt":"画面前景横置一道黑白相间的铁路道口栏杆，下方可见铁轨与枕木，杂草丛生。中景是一条向画面深处延伸的土路，路面略显泥泞。左侧树林边缘站立一名身穿深色长外套的人物，全身可见，身形较小。右侧远处树林间隐约可见另一人影。背景是密集的白桦林，树干细长，地面覆盖枯黄杂草。整体光线为阴天漫射光，色调偏冷灰，树林深处有微弱亮光，氛围静谧。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:39:22-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (334).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.508,"observed_resolution":"normal","observation_limits":[],"id":"VP-b6f26fdd83e4fe29","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-606e8a978be1f97d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (374).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"高角度俯视的深色广场，右侧一名穿浅色长外套的人物站立，手持长杆喷射出明亮的橙黄色火焰，周围散布着红白相间的方形箱体和若干站立围观的深色人影。","analysis":"画面采用高角度俯视构图，主体人物位于右侧，全身可见，呈站立姿态。一道明亮的橙黄色火焰从人物手中向左侧水平延伸，形成强烈的视觉引导线。环境为大面积深灰色地面，周围分布着红白相间的方形物体和零散的人影。光线以火焰为主，照亮了周围区域，与暗色背景形成高对比度，色彩以冷灰与暖橙为主。","prompt":"高角度俯视镜头，深灰色广场地面占据大部分画面。右侧一名身穿浅色长外套的人物全身可见，站立姿态，手持长杆向左侧喷射出明亮的橙黄色火焰，火焰呈水平长条状延伸。周围散布着数个红白相间的方形箱体，箱体顶部有圆形细节。画面边缘分布着若干身穿深色或红色衣物的人物，呈站立围观姿态。整体色调偏冷，火焰的暖橙色光在暗色环境中形成强烈对比，光影层次分明。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T22:57:14+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (374).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.495,"observed_resolution":"normal","observation_limits":[],"id":"VP-70e8f0d7965a6dee","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-72acd9b85563f921","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (381).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"室内场景中，一男一女并排坐着。左侧男子穿浅色外套内搭黑色高领，双手交握；右侧女子穿浅色长袖衣物，双手交叠于膝上。背景可见高背椅、台灯及木质家具。","analysis":"画面采用平视角度，人物占据画面主要位置，呈现上半身至大腿部分。左侧男子身形稍宽，右侧女子身形修长。室内光线柔和，右侧台灯提供暖色光源，照亮女子面部及衣物，左侧男子面部受光较均匀。背景家具轮廓清晰，整体色调偏暖，明暗对比适中，营造出安静的室内氛围。","prompt":"室内场景，一男一女并排坐着。左侧男子金发，穿浅灰色开襟外套，内搭黑色高领衫，双手交握于身前，神情严肃。右侧女子金发带刘海，穿米白色长袖上衣，双手交叠放在膝盖上，目光直视前方。背景是暖色调的室内环境，中间有一把高背木椅，右侧有一盏亮着的台灯，灯罩呈白色，灯座为深色。左侧可见部分木质家具和金属装饰物。地面铺有地毯，前景有黄色靠垫。整体光线柔和，人物面部清晰，衣物褶皱自然，环境细节丰富。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T22:57:25+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (381).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.521,"observed_resolution":"normal","observation_limits":[],"id":"VP-5e2336988d79598a","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-18b1235c94e5e9e3","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (379).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"两名人物在灰蓝色天空背景下相对而立，左侧男子戴深色帽穿黑衣，右侧人物穿红褐色外套，两人均呈侧面轮廓，面部朝向彼此。","analysis":"画面采用平视角度，人物占据画面左右两侧，中间留出大片天空空间。左侧人物可见头部至胸部，右侧人物可见头部至肩部。光线柔和均匀，无明显阴影，色彩以冷调天空与暖调衣物形成对比，人物轮廓清晰，背景纯净无杂物。","prompt":"两名人物在灰蓝色天空背景下相对而立，左侧男子戴深色平顶帽，穿黑色高领衣物，右侧人物留浅棕色短发，穿红褐色外套内搭黄色衣领，两人均呈侧面轮廓，面部朝向彼此，视线交汇。画面采用平视角度，人物占据左右两侧，中间留出大片天空空间，光线柔和均匀，色彩以冷调天空与暖调衣物形成对比，人物轮廓清晰，背景纯净无杂物。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T22:57:33+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (379).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.489,"observed_resolution":"normal","observation_limits":[],"id":"VP-5d7c28f5a0317685","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-650c363ad0827de3","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (362).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"前景为大面积剧烈燃烧的火焰，占据画面下半部。背景昏暗室内，一名戴头盔的人物站立于火焰后方中央，左侧可见家具轮廓。","analysis":"构图上，前景火焰占据画面约60%面积，形成强烈的视觉屏障。背景人物位于中轴线偏右，仅上半身及头部清晰可见，下半身被火焰遮挡。人物相对火焰显得较小，处于暗部。光线主要来自前景火光，向上投射暖橙色光晕，背景环境处于低照度阴影中，明暗对比强烈。","prompt":"画面前景被巨大的橙黄色火焰占据，火舌向上翻卷，亮度极高，遮蔽了地面细节。在火焰后方的昏暗室内背景中，一名身穿深色衣物、头戴头盔的人物站立在画面中央偏右位置，仅上半身可见，面部隐没在阴影中。左侧背景隐约可见深色的家具或桌案轮廓。整体色调以暖橙色火光与深褐色阴影为主，前景明亮，背景幽暗，呈现出一种被火光包围的压抑视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T22:57:40+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (362).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.524,"observed_resolution":"normal","observation_limits":[],"id":"VP-efb6ff6d44967240","origin":"visual"},{"work_id":"src-1fe33f4c8b5fd364","frame_id":"FG-34ca36ac42ac1583","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (330).jpg","source_page":"https://film-grab.com/2014/06/01/fahrenheit-451/","scene":"两名穿着棕色粗花呢外套的男子并排站立在树林中，背景是密集的垂直树干。两人均系着花纹丝巾，手持烟斗，面部表情平静，目光直视前方。","analysis":"画面采用对称构图，两名男子占据前景主要位置，仅上半身可见。背景由垂直排列的深色树干构成，形成重复的几何纹理。光线柔和均匀，没有强烈的明暗对比，整体色调偏向自然的棕褐色与灰绿色，营造出一种沉静、复古的氛围。","prompt":"两名外貌相似的男子并排站立在树林中，身穿棕色粗花呢西装外套，内搭橄榄绿衬衫，颈部系着蓝紫色花纹丝巾。两人手中各持一支烟斗，面部表情严肃且平静，目光直视镜头。背景是密集的垂直树干，树皮呈深褐色，远处隐约可见灰绿色的枝叶。光线为柔和的自然散射光，没有明显的阴影，整体色调偏暖，呈现出一种复古且略带超现实感的视觉效果。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T22:57:52+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (330).jpg","observed_dimensions":[1024,551],"source_thumbnail_dimensions":[500,269],"source_image_match_mae":0.517,"observed_resolution":"normal","observation_limits":[],"id":"VP-ba8fb8c6896fa030","origin":"visual"}]};